//! 🔗️ Bounded actual GSUB ligature sets borrow original glyph sequence and captured font authority.
use super::{FontLookup,super::{FontFace,FontProgress,FontReader,kerning::Index}};
use semio_framework_value::retirement::{RetireOwned,RetirementCursor};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct FontLigatureMatch{pub glyph:u16,pub consumed:usize}
semio_framework_value::artifact_retire_leaf!(FontLigatureMatch);
pub struct FontLigatureCursor{face:FontFace,lookup:FontLookup,glyph_pointer:usize,glyph_count:usize,start:usize,max_work:u64,phase:u8,sub:usize,at:usize,probe:Option<Index>,set:usize,ligature_at:usize,ligature_count:usize,ligature:usize,components:usize,component_at:usize,output:Option<FontLigatureMatch>,work:u64,cancelled:bool,failure:Option<String>}
impl RetireOwned for FontLigatureCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.failure.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.failure.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl FontLigatureCursor{
 pub fn new(face:FontFace,lookup:FontLookup,glyphs:&[u16],start:usize,max_work:u64)->Self{let invalid=face.gsub.is_none()||lookup.kind!=4||lookup.flags!=0&&lookup.flags!=8||start>=glyphs.len()||!(1..=1000000000).contains(&max_work);Self{face,lookup,glyph_pointer:glyphs.as_ptr()as usize,glyph_count:glyphs.len(),start,max_work,phase:0,sub:0,at:0,probe:None,set:0,ligature_at:0,ligature_count:0,ligature:0,components:0,component_at:0,output:None,work:0,cancelled:false,failure:invalid.then(||"Invalid font ligature authority".into())}}
 fn next_sub(&mut self){self.sub+=1;self.probe=None;self.phase=0;}
 fn step(&mut self,bytes:&[u8],glyphs:&[u16])->Result<(),String>{if bytes.len()!=self.face.byte_length||glyphs.as_ptr()as usize!=self.glyph_pointer||glyphs.len()!=self.glyph_count{return Err("Captured font ligature source changed".into());}let r=FontReader::new(bytes,self.face.gsub.ok_or("Font ligature authority missing")?)?;match self.phase{
  0=>{if self.sub==self.lookup.subtables{self.phase=4;return Ok(());}self.at=self.lookup.offset+usize::from(r.u16(self.lookup.offset+6+self.sub*2)?);if r.u16(self.at)?!=1{return Err("Unsupported font ligature format".into());}self.probe=Some(Index::new(r,self.at+usize::from(r.u16(self.at+2)?),glyphs[self.start],false)?);self.phase=1;},
  1=>{if !self.probe.as_mut().unwrap().step(r)?{return Ok(());}let coverage=self.probe.as_ref().unwrap().result();self.probe=None;if coverage<0{self.next_sub();return Ok(());}let count=usize::from(r.u16(self.at+4)?);if coverage as usize>=count{return Err("Font ligature coverage exceeds set authority".into());}self.set=self.at+usize::from(r.u16(self.at+6+coverage as usize*2)?);self.ligature_count=usize::from(r.u16(self.set)?);r.range(self.set+2,self.ligature_count*2)?;self.ligature_at=0;self.phase=2;},
  2=>{if self.ligature_at==self.ligature_count{self.next_sub();return Ok(());}self.ligature=self.set+usize::from(r.u16(self.set+2+self.ligature_at*2)?);self.ligature_at+=1;self.components=usize::from(r.u16(self.ligature+2)?);if self.components==0{return Err("Font ligature has no components".into());}r.range(self.ligature+4,(self.components-1)*2)?;if self.components>glyphs.len()-self.start{return Ok(());}self.component_at=1;self.phase=3;},
  3=>{if self.component_at==self.components{let glyph=r.u16(self.ligature)?;if glyph>=self.face.glyphs{return Err("Font ligature glyph exceeds authority".into());}self.output=Some(FontLigatureMatch{glyph,consumed:self.components});self.phase=4;return Ok(());}if r.u16(self.ligature+2+self.component_at*2)?!=glyphs[self.start+self.component_at]{self.phase=2;return Ok(());}self.component_at+=1;},
  _=>return Err("Font ligature stage invalid".into()),
 }Ok(())}
 pub fn advance(&mut self,bytes:&[u8],glyphs:&[u16],grant:usize)->Result<FontProgress,String>{if grant==0{return Err("Invalid font ligature work grant".into());}if self.cancelled{return Err("Font ligature cancelled".into());}if let Some(error)=&self.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==4{break;}if self.work==self.max_work{self.failure=Some("Font ligature work limit exceeded".into());return Err(self.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes,glyphs){self.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(FontProgress{phase:match self.phase{0=>"subtable",1=>"coverage",2=>"ligature",3=>"components",_=>"complete"},work:self.work,done:self.phase==4})}
 pub fn result(&self)->Result<Option<FontLigatureMatch>,String>{if self.phase!=4||self.cancelled||self.failure.is_some(){return Err("Font ligature incomplete".into());}Ok(self.output)}
 pub fn cancel(&mut self){self.cancelled=true;}
}
